import { createHash, createHmac, timingSafeEqual } from 'node:crypto';
import { isIP } from 'node:net';

/**
 * Dedicated headers for trusted UI-server -> API identity delegation.
 *
 * These headers are generated by the UI SERVER, never Angular.
 */
export const AUTH_DELEGATION_HEADERS = {
  ip: 'x-manatos-auth-client-ip',
  time: 'x-manatos-auth-client-time',
  signature: 'x-manatos-auth-client-signature',
} as const;

/** Allowed clock difference between the API and UI server. */
export const AUTH_DELEGATION_MAX_SKEW_MS = 30_000;

/**
 * HTTP headers may be absent, in which case Express returns undefined.
 *
 * With TypeScript's exactOptionalPropertyTypes enabled, an optional
 * property does not automatically permit an explicitly undefined value.
 *
 * Allow both missing properties and undefined header values.
 * The verifier below still rejects incomplete delegation.
 */
export interface AuthClientDelegationHeaders {
  readonly ip?: string | undefined;
  readonly time?: string | undefined;
  readonly signature?: string | undefined;
}

/**
 * Bind the client IP to a particular request.
 *
 * Signing the HTTP method, URL and request-body digest means that
 * a signature for one login request cannot authorize a different
 * request or a different claimed IP address.
 */
function proof(
  secret: string,
  ip: string,
  time: string,
  method: string,
  path: string,
  body: unknown,
): Buffer {
  const hash = createHash('sha256').update(JSON.stringify(body)).digest('hex');

  return createHmac('sha256', secret)
    .update(`v1\n${time}\n${method.toUpperCase()}\n${path}\n${ip}\n${hash}`)
    .digest();
}

function checkSecret(secret: string): void {
  if (Buffer.byteLength(secret, 'utf8') < 32) {
    throw new Error('AUTH_DELEGATION_SECRET must contain at least 32 UTF-8 bytes.');
  }
}

/**
 * Called by the trusted NG1 Node host when calling the API.
 *
 * The secret stays exclusively in server environment configuration.
 */
export function signAuthClientIp(
  secret: string,
  ip: string,
  method: string,
  path: string,
  body: unknown,
  now = Date.now(),
): Record<string, string> {
  checkSecret(secret);

  if (isIP(ip) === 0) {
    throw new Error('Invalid client IP for Auth delegation.');
  }

  const time = String(now);

  return {
    [AUTH_DELEGATION_HEADERS.ip]: ip,
    [AUTH_DELEGATION_HEADERS.time]: time,
    [AUTH_DELEGATION_HEADERS.signature]: proof(secret, ip, time, method, path, body).toString(
      'hex',
    ),
  };
}

/**
 * Called at the public API boundary.
 *
 * No headers:
 *   Ordinary direct API request; use the actual connection IP.
 *
 * Complete, valid headers:
 *   Trusted UI-server request; use its authenticated client IP.
 *
 * Missing, invalid or expired headers:
 *   Reject the delegation. Never trust a user-supplied IP merely
 *   because a request contains an X-Forwarded-For header.
 */
export function verifyAuthClientIp(
  secret: string | undefined,
  headers: AuthClientDelegationHeaders,
  method: string,
  path: string,
  body: unknown,
  now = Date.now(),
): string | null {
  if (!headers.ip && !headers.time && !headers.signature) {
    return null;
  }

  if (
    !secret ||
    Buffer.byteLength(secret, 'utf8') < 32 ||
    !headers.ip ||
    !headers.time ||
    !headers.signature
  ) {
    throw new Error('Untrusted Auth client delegation.');
  }

  if (
    isIP(headers.ip) === 0 ||
    !/^\d{13}$/.test(headers.time) ||
    !/^[a-f0-9]{64}$/.test(headers.signature)
  ) {
    throw new Error('Invalid Auth client delegation.');
  }

  if (Math.abs(now - Number(headers.time)) > AUTH_DELEGATION_MAX_SKEW_MS) {
    throw new Error('Expired Auth client delegation.');
  }

  const expected = proof(secret, headers.ip, headers.time, method, path, body);

  const received = Buffer.from(headers.signature, 'hex');

  if (!timingSafeEqual(expected, received)) {
    throw new Error('Invalid Auth client delegation.');
  }

  return headers.ip;
}
